<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SJR · Design Workspace V3.1</title><style>
:root{font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#162b4b;background:#f4f7fb}*{box-sizing:border-box}body{margin:0}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}.shell{display:grid;grid-template-columns:234px minmax(0,1fr);min-height:100vh}.sidebar{background:#122443;color:#eff6ff;padding:27px 16px;display:flex;flex-direction:column;gap:25px}.brand{font-weight:800;display:flex;align-items:center;gap:11px;font-size:16px;padding:2px 5px}.logo{background:#3779e7;padding:12px;border-radius:13px}.sidecap{font-size:10px;color:#98b4dd;letter-spacing:2px;font-weight:800;margin:14px 9px}.nav{padding:13px;border-radius:11px;background:#244775;font-size:13px;font-weight:700}.note{margin-top:auto;color:#9ab0ce;font-size:11px;line-height:1.7;border-top:1px solid #36506d;padding-top:15px}.main{min-width:0}.topbar{height:75px;background:#fff;border-bottom:1px solid #e5ebf4;display:flex;align-items:center;justify-content:space-between;padding:0 36px;font-size:12px}.topbar strong{font-size:14px}.role{display:flex;align-items:center;gap:10px}.role select{border:1px solid #d8e3ef;border-radius:10px;padding:10px;background:white;color:#1d3557}.pill{border-radius:999px;background:#e9f1ff;color:#2862bd;padding:7px 11px;font-size:11px;font-weight:800}.page{max-width:1500px;margin:0 auto;padding:34px 36px}.eyebrow{color:#2a6edc;font-size:10px;letter-spacing:2px;font-weight:900}.heading{display:flex;justify-content:space-between;align-items:end;gap:15px;margin-bottom:26px}h1{font-size:30px;margin:6px 0 7px;letter-spacing:-1px}p.sub{margin:0;color:#7186a3;font-size:13px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin-bottom:24px}.stat{border:1px solid #dde7f3;background:#fff;padding:19px 20px;border-radius:15px;box-shadow:0 8px 25px #10274405;display:flex;align-items:center;justify-content:space-between}.stat b{display:block;font-size:30px;letter-spacing:-1px}.stat small{font-size:11px;color:#7589a3}.stat span{border-radius:12px;background:#edf4ff;padding:10px;font-size:18px}.board{background:#fff;border:1px solid #dce6f2;border-radius:17px;overflow:hidden;box-shadow:0 10px 35px #122b4b09}.boardHead{display:flex;justify-content:space-between;align-items:center;padding:22px;border-bottom:1px solid #e6edf6;gap:15px;flex-wrap:wrap}.boardHead h2{margin:0 0 4px;font-size:18px}.boardHead small{color:#8a9db7}.tools{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.tools input,.tools select{border:1px solid #d9e4f0;background:#fff;border-radius:10px;padding:11px 13px;font-size:12px;color:#253e60}.tools input{width:min(255px,40vw)}.btn{border:1px solid #d7e3f3;background:#fff;border-radius:10px;padding:10px 14px;color:#245291;font-size:12px;font-weight:750}.btn.primary{background:#246de7;color:#fff;border-color:#246de7}.btn.danger{border-color:#f1c9c9;color:#b14444}.tableWrap{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:790px}th{padding:15px 19px;text-align:left;background:#f7f9fc;color:#7488a3;font-size:11px}td{padding:19px;border-top:1px solid #edf2f8;font-size:12px}td strong{display:block;margin-bottom:5px;font-size:13px}td small{color:#8495ab}.status{white-space:nowrap;border-radius:30px;padding:7px 10px;font-size:10px;font-weight:800;background:#ede8ff;color:#7044c0}.status.progress{background:#e8f1ff;color:#2166c6}.status.review{background:#fff1db;color:#a46b15}.status.revision{background:#ffe5e5;color:#af3333}.status.done{background:#e5f7ed;color:#278253}.priority{font-weight:750;color:#d37c36}.empty{text-align:center;padding:40px;color:#869bb3}.foot{padding:13px 21px;color:#8196ae;font-size:11px;border-top:1px solid #eef3f8}.overlay{position:fixed;inset:0;background:#09203e8c;z-index:10;display:none;align-items:stretch;justify-content:flex-end}.overlay.show{display:flex}.drawer{width:min(1050px,94vw);height:100vh;background:#f7f9fd;display:flex;flex-direction:column;box-shadow:-15px 0 60px #0002}.drawerHead{padding:20px 30px;background:#fff;border-bottom:1px solid #e2eaf4;display:flex;justify-content:space-between;align-items:center;gap:12px}.drawerHead h2{font-size:22px;margin:5px 0}.muted{color:#8092ad;font-size:12px}.drawerBody{overflow:auto;padding:24px 28px;flex:1}.detailGrid{display:grid;grid-template-columns:1.18fr .82fr;gap:17px}.stack{display:flex;flex-direction:column;gap:16px}.card{background:#fff;border:1px solid #e0e9f4;border-radius:15px;padding:20px}.card h3{font-size:15px;margin:0 0 15px;display:flex;align-items:center;gap:8px}.card h3 i{font-style:normal;background:#eaf2fe;color:#2368ce;border-radius:10px;padding:8px}.heroBrief{border-color:#afcef9;background:linear-gradient(135deg,#f0f6ff,#fff)}.heroBrief h3{font-size:18px}.heroBrief p{white-space:pre-wrap;font-size:14px;line-height:1.75;color:#314d71}.infoGrid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.info{background:#f6f8fc;padding:12px;border-radius:9px}.info small{display:block;color:#8194ad;font-size:10px;margin-bottom:5px}.info strong{font-size:12px}.file{display:flex;gap:10px;align-items:center;justify-content:space-between;border-top:1px solid #edf2f8;padding:13px 0;font-size:11px}.file b{overflow-wrap:anywhere}.file small{color:#8496af}.actionPanel{background:#fdfefe;border:2px solid #d1e1f8}.actionPanel textarea{resize:vertical;min-height:95px;width:100%;padding:12px;border:1px solid #d6e2f1;border-radius:10px;margin:9px 0 12px}.actionPanel input[type=file]{width:100%;padding:12px;border:1px dashed #98bdf7;border-radius:10px;background:#f3f7fe}.selected{font-size:11px;color:#5d7595;margin:10px 0}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.step{font-size:11px;color:#6180a9;background:#edf4ff;border-radius:9px;padding:10px;margin-bottom:15px}.drawerFoot{display:flex;justify-content:space-between;gap:10px;padding:14px 28px;background:white;border-top:1px solid #e2eaf4}.notice{font-size:12px;color:#3169b0;padding:12px;border-radius:9px;background:#edf4ff}.hide{display:none!important}@media(max-width:1000px){.shell{grid-template-columns:66px 1fr}.sidebar{padding:20px 9px}.brand>span:last-child,.sidecap,.nav,.note{display:none}.page{padding:24px}.stats{grid-template-columns:repeat(2,1fr)}.detailGrid{grid-template-columns:1fr}}@media(max-width:600px){.topbar{padding:0 15px}.topbar strong{font-size:11px}.page{padding:16px}.stats{gap:8px}.stat{padding:13px}.stat b{font-size:23px}.heading{margin-bottom:15px}.drawer{width:100vw}.drawerHead{padding:17px}.drawerBody{padding:14px}.drawerFoot{padding:12px}.infoGrid{grid-template-columns:1fr 1fr}}

/* V3.1 — fokus tampilan penuh, tidak memakai drawer sempit */
.overlay{background:#f4f7fb;align-items:stretch;justify-content:center}
.overlay.show{display:flex}
.drawer{width:100%;height:100dvh;max-width:none;box-shadow:none;background:#f4f7fb}
.drawerHead{padding:22px clamp(20px,5vw,72px);flex-shrink:0}
.drawerHead>div{min-width:0}
.drawerHead h2{font-size:27px;line-height:1.2;overflow-wrap:anywhere}
.drawerBody{width:100%;max-width:1450px;margin:0 auto;padding:26px clamp(20px,4vw,52px) 42px;min-height:0}
.detailGrid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:22px;align-items:start}
.detailGrid>.stack{min-width:0;gap:20px}
.detailGrid .card{padding:24px;border-radius:18px;box-shadow:0 5px 24px #19354c08}
.heroBrief{background:linear-gradient(115deg,#ebf4ff,#fff);border:1.5px solid #a9ccfb}
.heroBrief p{font-size:16px;line-height:1.7}
.infoGrid{gap:12px}
.info{padding:16px}
.card h3{font-size:16px}
.actionPanel{border:1.5px solid #a9ccfb;background:#fff}
.drawerFoot{padding:15px clamp(20px,5vw,72px)}
.file{font-size:12px;gap:16px}
@media(max-width:900px){.detailGrid{grid-template-columns:1fr}.drawerBody{padding:18px}.drawerHead{padding:18px}.drawerFoot{padding:12px 18px}.drawerHead h2{font-size:21px}}
@media(max-width:560px){.drawerFoot .muted{display:none}.detailGrid .card{padding:17px}.drawerHead{align-items:start}}

/* V3.2 — detail stays inside the application shell, preserving navigation */
.overlay{position:fixed!important;inset:75px 0 0 234px!important;background:#f4f7fb!important;z-index:10;align-items:stretch;justify-content:stretch}
.overlay.show{display:flex}
.drawer{width:100%!important;max-width:none!important;height:calc(100dvh - 75px)!important;box-shadow:none!important;min-width:0}
.drawerHead{padding:20px 36px;border-bottom:1px solid #e2eaf4}
.drawerBody{max-width:1450px;padding:22px 36px 38px}
.drawerFoot{padding:13px 36px}
.detailGrid{grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:18px}
.detailGrid>.stack{gap:16px}
.detailGrid .card{padding:21px}
@media(max-width:1000px){.overlay{left:66px!important}.drawerBody{padding:18px 22px 28px}.drawerHead,.drawerFoot{padding:16px 22px}}
@media(max-width:760px){.detailGrid{grid-template-columns:1fr}.overlay{left:66px!important}}
@media(max-width:600px){.drawerHead,.drawerFoot{padding:12px 15px}.drawerBody{padding:14px}.drawerHead h2{font-size:20px}}

/* V3.4 — Design detail 70:30; keep the original sidebar and header */
@media (min-width:901px){
  .detailGrid{grid-template-columns:minmax(0,7fr) minmax(0,3fr);gap:18px;align-items:start}
  .detailGrid>.stack{min-width:0}
  .detailGrid .card{min-width:0}
  .detailGrid .infoGrid{grid-template-columns:1fr;gap:9px}
}
@media (max-width:900px){.detailGrid{grid-template-columns:minmax(0,1fr)}}

/* V3.5 — Informasi Pekerjaan: baris ala referensi Task Information */
.detailGrid #details.infoGrid{display:flex!important;flex-direction:column;gap:0}
.task-info-row{display:grid;grid-template-columns:minmax(92px,39%) 10px minmax(0,1fr);gap:7px;align-items:start;padding:9px 0;border-bottom:1px solid #eef2f8;font-size:12px;line-height:1.55}
.task-info-row:last-child{border-bottom:0}
.task-info-label{color:#617b9d;font-weight:500}
.task-info-colon{color:#91a3bb}
.task-info-value{color:#1b3b6b;font-weight:700;overflow-wrap:anywhere}
.task-info-badge{display:inline-flex;align-items:center;border-radius:7px;padding:5px 11px;font-size:11px;font-weight:800;line-height:1.4}
.task-info-badge.high{background:#fee6e7;color:#b43a43}
.task-info-badge.normal{background:#e8f5ee;color:#237a54}
.task-info-badge.status-new{background:#e9eefe;color:#455faa}
.task-info-badge.status-progress{background:#e6f0ff;color:#2267bd}
.task-info-badge.status-review{background:#fff0d7;color:#9c6b21}
.task-info-badge.status-revision{background:#fff0ed;color:#bd5642}
.task-info-badge.status-done{background:#e5f7ed;color:#268052}
@media(max-width:1100px){.task-info-row{grid-template-columns:minmax(88px,39%) 9px minmax(0,1fr)}}

/* V3.6 — Lampiran Referensi: tabel enterprise read-only */
.reference-table-wrap{margin-top:14px;overflow-x:auto;border:1px solid #dde7f3;border-radius:12px}
.reference-table{width:100%;min-width:685px;border-collapse:collapse;font-size:12px;text-align:left}
.reference-table thead{background:#edf4fd;color:#26426d}
.reference-table th{padding:12px 10px;font-size:11px;font-weight:800;white-space:nowrap}
.reference-table td{padding:12px 10px;border-top:1px solid #e6eef8;vertical-align:middle;color:#29436a}
.reference-table td.ref-file-name{font-weight:700;overflow-wrap:anywhere;max-width:270px}
.reference-table .ref-file-badge{display:inline-grid;place-items:center;width:31px;min-width:31px;height:34px;border-radius:7px;font-size:9px;font-weight:800;background:#e8f1fd;color:#1e6cbd;margin-right:7px;vertical-align:middle}
.reference-table .ref-file-badge.pdf{background:#fee8e9;color:#c63442}
.reference-table .ref-file-badge.zip{background:#f0eaff;color:#6941ae}
.reference-table td.ref-file-name .name{display:inline;line-height:1.5}
.reference-table button.ref-download{border:1px solid #d5e0ee;border-radius:8px;background:#f6f9fd;color:#8093af;padding:7px 9px;cursor:not-allowed;white-space:nowrap}
.reference-note{font-size:11px;line-height:1.55;margin-top:12px}

/* V3.7: delivery archive and review workflow */
.delivery-archive{display:flex;flex-direction:column;gap:12px;margin-bottom:16px}
.delivery-version{background:#fff;border:1px solid #dce7f5;border-radius:12px;overflow:hidden}
.delivery-version-head{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;background:#f1f6fd;padding:12px 14px;font-size:12px}
.delivery-version-body{padding:14px;font-size:12px}
.delivery-version-body p{margin:0 0 10px;white-space:pre-wrap;line-height:1.65}
.delivery-file{display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:1px solid #edf2f8;padding:9px 0;overflow-wrap:anywhere;font-size:12px}
.delivery-file small{color:#7890ab}
.revision-request{background:#fff5ee;border:1px solid #f4d8bd;border-radius:11px;padding:13px 14px;color:#965b2e;margin:0 0 14px;font-size:12px;line-height:1.6}
.actionPanel .selected{overflow-wrap:anywhere}
.actionPanel .delivery-archive-title{font-size:13px;font-weight:800;margin:10px 0}
.actionPanel .notice{line-height:1.65}

/* V3.8 UI refinements */
.design-uploader{border:1.5px dashed #9dbffa;border-radius:13px;background:#f4f8ff;padding:20px;text-align:center;margin:9px 0;cursor:pointer;display:block;color:#1c57ac;font-weight:750;font-size:13px}
.design-uploader:hover{background:#ecf4ff}
.design-uploader small{display:block;color:#7a8da9;font-size:11px;margin-top:8px;font-weight:400}
.design-uploader input{position:absolute;opacity:0;width:1px;height:1px}
.design-file-list{border:1px solid #dce7f5;border-radius:11px;overflow:hidden;margin:11px 0 14px}
.design-file-row{display:flex;gap:12px;justify-content:space-between;align-items:center;padding:10px 12px;border-bottom:1px solid #e9eff8;font-size:12px}
.design-file-row:last-child{border-bottom:0}.design-file-row strong{overflow-wrap:anywhere;flex:1}
.design-file-row .btn{padding:6px 10px}.design-empty{padding:14px;color:#8395ae;font-size:12px}
.version-state{border-radius:30px;padding:5px 9px;font-size:10px;font-weight:800;background:#e8efff;color:#4269b7}
.version-state.revision{background:#ffe9e2;color:#9b4f28}.version-state.done{background:#e5f7ed;color:#277c4c}.version-state.review{background:#fff1d8;color:#9b6a20}
.revision-request .rev-meta{font-size:11px;margin-bottom:6px;color:#aa673e;font-weight:800}
.timeline{border-left:2px solid #dce8f8;margin-left:7px;padding:0 0 0 16px}
.timeline-item{position:relative;padding:0 0 16px;font-size:12px;color:#344f72;line-height:1.6}
.timeline-item:before{content:'';position:absolute;left:-22px;top:5px;width:9px;height:9px;border-radius:50%;background:#397ce6;border:2px solid #fff;box-shadow:0 0 0 1px #bfdbff}
.timeline-item:last-child{padding-bottom:0}
.timeline-item small{display:block;color:#8094af;margin-top:3px;font-size:10px}

#reset,#role{display:none!important}
.topbar .pill{background:#e3f4ec;color:#167a45}
 .reference-table a.ref-download-active{display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;box-sizing:border-box;padding:0;text-decoration:none;cursor:pointer;background:#fff;color:#274d7b;border:1px solid #d5e0ee;border-radius:9px;vertical-align:middle;transition:background .15s,border-color .15s}
 .reference-table a.ref-download-active:hover{background:#edf4ff;border-color:#9ab9e9}
 .reference-table a.ref-download-active:focus-visible{outline:3px solid #8bb5f7;outline-offset:2px}
 .reference-table a.ref-download-active svg{display:block;flex-shrink:0}

/* SJR OPTION A — hasil desain: image thumbnails + file-type cards */
.delivery-version-body .delivery-file-card{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid #e9eff8;min-width:0}
.delivery-file-preview{width:58px;height:58px;flex:0 0 58px;border:1px solid #dce7f5;border-radius:10px;background:#f2f6fc;overflow:hidden;display:flex;align-items:center;justify-content:center}
.delivery-file-preview img{width:100%;height:100%;object-fit:cover;display:block}
.delivery-file-icon{width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800;letter-spacing:.03em;color:#526d93}
.delivery-file-icon.delivery-pdf{background:#fff0f0;color:#b73848}
.delivery-file-icon.delivery-zip{background:#f3edff;color:#7550ae}
.delivery-file-icon.delivery-image-fallback{background:#eaf5ff;color:#315e9d}
.delivery-file-meta{min-width:0;flex:1;display:flex;flex-direction:column;gap:5px}
.delivery-file-meta strong{font-size:12px;color:#193255;overflow-wrap:anywhere;line-height:1.4}
.delivery-file-meta small{font-size:11px;color:#758ca9}
.delivery-file-actions{margin-left:auto;flex-shrink:0}
.delivery-file-download{display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;border:1px solid #d5e0ee;background:#fff;border-radius:9px;color:#274d7b;text-decoration:none}
.delivery-file-download:hover{background:#edf4ff;border-color:#9ab9e9}
.delivery-file-download:focus-visible{outline:3px solid #8bb5f7;outline-offset:2px}
