small></div><div class="tools"><input id="search" placeholder="⌕  Cari SJR, klien, pekerjaan..."><select id="filter"><option value="all">Semua status</option><option value="new">Menunggu Designer</option><option value="progress">Dalam Proses</option><option value="review">Review Marketing</option><option value="revision">Perlu Revisi</option><option value="done">Selesai Review</option></select><select id="sort"><option value="deadline">Deadline terdekat</option><option value="recent">SJR terbaru</option></select></div></div><div class="tableWrap"><table><thead><tr><th>NO. SJR / PEKERJAAN</th><th>KLIEN</th><th>DEADLINE DESIGNER</th><th>STATUS</th><th>PRIORITAS</th><th>AKSI</th></tr></thead><tbody id="tbody"></tbody></table></div><div class="foot" id="count"></div></div></main></div></div><div class="overlay" id="overlay"><section class="drawer"><div class="drawerHead"><div><span class="eyebrow" id="jobNo"></span><h2 id="jobName"></h2><span class="muted" id="jobLine"></span></div><button class="btn" id="close">✕ &nbsp; Tutup</button></div><div class="drawerBody"><div class="detailGrid"><div class="stack"><div class="card heroBrief"><h3>✦ &nbsp; Brief Designer</h3><p id="brief"></p><div class="step" id="deadline"></div></div><div class="card"><h3><i>⇧</i> Lampiran Referensi <span id="referenceCount" class="ref-count"></span></h3><div id="files" class="reference-table-wrap"></div><p class="muted reference-note">Lampiran referensi tersedia untuk Marketing pemilik pekerjaan dan Designer yang berwenang.</p></div><div class="card actionPanel"><div class="step">DESIGNER → REVIEW MARKETING → PRODUKSI</div><h3 id="actionTitle">Serahkan Hasil Desain</h3><div id="actionContent"></div></div></div><div class="stack"><div class="card"><h3><i>▤</i> Informasi Pekerjaan</h3><div class="infoGrid" id="details"></div><p class="muted" id="spec" style="line-height:1.6"></p></div><div class="card"><h3>◷ &nbsp; Riwayat Aktivitas</h3><div id="history" class="muted"></div></div></div></div></div></div><div class="drawerFoot"><span class="muted">Tahap 2A · Pengiriman Designer disimpan di database pengujian</span><button class="btn" id="closeBottom">Kembali ke Design Workspace</button></div></section></div><script>
const isDesigner=@json($isDesigner);
const originals=@json($jobs);let jobs=[],active=null;let currentFiles=[];const labels={new:'Menunggu Designer',progress:'Dalam Proses',review:'Review Marketing',revision:'Perlu Revisi',done:'Disetujui Marketing'};const el=id=>document.getElementById(id);const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function reset(){jobs=structuredClone(originals).map(x=>({...x,history:(x.history&&x.history.length?x.history:[{message:'Brief diterima oleh divisi Designer',by:'Sistem',at:'Data pengujian'}]),submissions:x.submissions||[],revisions:[],revisionNote:''}));active=null;el('overlay').classList.remove('show');render()}function render(){let role=(isDesigner?'designer':'marketing');el('pageSub').textContent=role==='designer'?'Pantau antrean desain, prioritas, dan deadline dalam satu tempat.':'Tinjau hasil desain yang dikirim Designer, lalu setujui atau minta revisi.';el('listTitle').textContent=role==='designer'?'Design Queue':'Marketing Design Review';el('sall').textContent=jobs.length;el('snew').textContent=jobs.filter(x=>x.status==='new').length;el('sprogress').textContent=jobs.filter(x=>['progress','revision'].includes(x.status)).length;el('sreview').textContent=jobs.filter(x=>x.status==='review').length;let query=el('search').value.toLowerCase(),f=el('filter').value;let list=jobs.filter(x=>(f==='all'||x.status===f)&&[x.id,x.name,x.client].join(' ').toLowerCase().includes(query));list.sort((a,b)=>el('sort').value==='recent'?b.id.localeCompare(a.id):a.deadline.localeCompare(b.deadline));el('tbody').innerHTML=list.length?list.map(x=>`<tr><td><strong>${safe(x.name)}</strong><small>${safe(x.id)}</small></td><td>${safe(x.client)}</td><td>${safe(x.deadline)}</td><td><span class="status ${safe(x.status)}">${safe(labels[x.status])}</span></td><td><span class="priority">${x.deadline<'2026-11-03'?'● Tinggi':'● Normal'}</span></td><td><button class="btn" data-open="${safe(x.id)}">Buka →</button></td></tr>`).join(''):'<tr><td class="empty" colspan="6">Tidak ada pekerjaan sesuai filter.</td></tr>';el('count').textContent=`Menampilkan ${list.length} dari ${jobs.length} pekerjaan (data pengujian)`;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openJob(b.dataset.open))}function stamp(){return new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short'}).format(new Date())}
function versionsHTML(job){const results=job.submissions||[];if(!results.length)return '';return '<div class="delivery-archive-title">Hasil Desain Terkirim · '+results.length+' versi</div><div class="delivery-archive">'+results.slice().reverse().map(v=>{const last=v.version===results.length;const state=last?(job.status==='done'?'Disetujui':job.status==='review'?'Menunggu Review':job.status==='revision'?'Perlu Revisi':'Terkirim'):'Sudah direvisi';const stateClass=state==='Disetujui'?'done':state==='Perlu Revisi'?'revision':'review';return '<div class="delivery-version"><div class="delivery-version-head"><strong>Versi '+v.version+'</strong><span class="version-state '+stateClass+'">'+state+'</span><span class="muted">'+safe(v.sentAt)+'</span></div><div class="delivery-version-body"><p><b>Catatan Designer:</b> '+safe(v.note)+'</p>'+v.files.map(f=>'<div class="delivery-file delivery-file-card"><div class="delivery-file-preview">'+(f.downloadUrl&&/\.(png|jpe?g|webp|gif|bmp)$/i.test(String(f.name||''))?'<img src="'+safe(f.downloadUrl)+'" alt="" loading="lazy" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\'"><span class="delivery-file-icon delivery-image-fallback" style="display:none">IMG</span>':'<span class="delivery-file-icon '+(/\.pdf$/i.test(String(f.name||''))?'delivery-pdf':/\.zip$/i.test(String(f.name||''))?'delivery-zip':'delivery-other')+'">'+(/\.pdf$/i.test(String(f.name||''))?'PDF':/\.zip$/i.test(String(f.name||''))?'ZIP':'FILE')+'</span>')+'</div><div class="delivery-file-meta"><strong title="'+safe(f.name)+'">'+safe(f.name)+'</strong><small>'+safe(String(f.name||'').split('.').pop().toUpperCase())+' · '+safe(f.sizeText||'—')+'</small></div><div class="delivery-file-actions">'+(f.downloadUrl?'<a class="delivery-file-download" href="'+safe(f.downloadUrl)+'" title="Unduh file" aria-label="Unduh '+safe(f.name)+'"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3v12"/><path d="m7 10 5 5 5-5"/><path d="M4 17v4h16v-4"/></svg></a>':'<span class="muted">—</span>')+'</div></div>').join('')+'</div></div>'}).join('')+'</div>'}
function logActivity(job,message,by){job.history.push({message,by,at:stamp()})}
function historyHTML(job){return '<div class="timeline">'+job.history.slice().reverse().map(h=>{const x=typeof h==='string'?{message:h,by:'Sistem',at:''}:h;return '<div class="timeline-item"><strong>'+safe(x.message)+'</strong><small>'+safe(x.by)+(x.at?' · '+safe(x.at):'')+'</small></div>'}).join('')+'</div>'}
function revisionHTML(job){const r=(job.revisions||[]).at(-1);if(job.status!=='revision'||!r)return '';return '<div class="revision-request"><div class="rev-meta">Revisi '+r.number+' · '+safe(r.at)+' · Marketing</div><strong>Permintaan Revisi dari Marketing</strong><div>'+safe(r.note)+'</div></div>'}
function bytesLabel(n){return n>=1048576?(n/1048576).toFixed(2)+' MB':n>=1024?(n/1024).toFixed(1)+' KB':n+' B'}
/* SJR_UNIFIED_LINK_V1: open work item linked from Job Workspace */
document.addEventListener('DOMContentLoaded',()=>{const aside=document.querySelector('.sidebar');if(aside){const a=document.createElement('a');a.href='/simple-jobs';a.textContent='← Job Workspace';a.style.cssText='display:block;color:#eaf1ff;text-decoration:none;border:1px solid #54739b;border-radius:9px;padding:11px;margin-top:12px;font-size:12px;font-weight:700';aside.insertBefore(a,aside.querySelector('.note'));}});
function sjrLinkedJob(){const code=new URLSearchParams(location.search).get('sjr');if(!code)return;const match=jobs.find(x=>x.id===code);if(match)openJob(match.id)}
function openJob(id){active=jobs.find(x=>x.id===id);if(!active)return;el('overlay').classList.add('show');el('jobNo').textContent='DESIGN / '+active.id;el('jobName').textContent=active.name;el('jobLine').textContent=active.client+' · '+labels[active.status];el('brief').textContent=active.brief;el('deadline').textContent='◷  Deadline Designer: '+active.deadline;const priorityLabel=active.deadline<'2026-11-03'?'Tinggi':'Normal';const detailRows=[['Nama Pekerjaan',active.name],['Tahap','Desain'],['Ditugaskan ke','Belum ditetapkan'],['Tanggal Penugasan','—'],['Deadline Designer',active.deadline],['Prioritas',priorityLabel],['Status',labels[active.status]],['Klien',active.client],['PIC Pelanggan',active.pic],['Target Pekerjaan',active.target],['Kuantitas',active.quantity]];el('details').innerHTML=detailRows.map(([k,v])=>`<div class="task-info-row"><span class="task-info-label">${safe(k)}</span><span class="task-info-colon">:</span><span class="task-info-value">${k==='Prioritas'?`<span class="task-info-badge ${priorityLabel==='Tinggi'?'high':'normal'}">${safe(v)}</span>`:k==='Status'?`<span class="task-info-badge status-${safe(active.status)}">${safe(v)}</span>`:safe(v)}</span></div>`).join('');el('spec').textContent='Detail pekerjaan: '+active.spec;el('referenceCount').textContent='('+active.files.length+')';
const fileTypes=(n)=>{let ext=String(n).split('.').pop().toUpperCase();return ext==='JPEG'?'JPG':ext};

el('files').innerHTML=active.files.length?`<table class="reference-table"><thead><tr><th>No.</th><th>Nama File</th><th>Tipe</th><th>Ukuran</th><th>Diupload Oleh</th><th>Tanggal</th><th>Aksi</th></tr></thead><tbody>${active.files.map(([n,c,url,size],i)=>{let ext=fileTypes(n);return `<tr><td>${i+1}</td><td class="ref-file-name"><span class="ref-file-badge ${safe(ext.toLowerCase())}">${safe(ext)}</span><span class="name" title="${safe(c)}">${safe(n)}</span></td><td>${safe(ext)}</td><td>${safe(size||'—')}</td><td>Marketing</td><td>—</td><td>${url?`<a class="ref-download ref-download-active" href="${safe(url)}" title="Unduh lampiran" aria-label="Unduh ${safe(n)}"><svg xmlns="http://www.w3.org/2000/svg" width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3v12"/><path d="m7 10 5 5 5-5"/><path d="M4 17v4h16v-4"/></svg></a>`:`<span class="muted">Tidak tersedia</span>`}</td></tr>`}).join('')}</tbody></table>`:'<p class="muted" style="padding:16px">Tidak ada lampiran referensi.</p>';el('history').innerHTML=historyHTML(active);let role=isDesigner?'designer':'marketing';const wrap=el('actionContent');const archive=versionsHTML(active);const revision=revisionHTML(active);
if(role==='designer'){
 if(active.status==='review'||active.status==='done'){
   el('actionTitle').textContent=active.status==='review'?'Menunggu Review Marketing':'Desain telah disetujui';
   wrap.innerHTML=archive+'<p class="notice">'+(active.status==='review'?'Hasil desain sudah diserahkan. Menunggu keputusan Marketing. Pengiriman ulang dinonaktifkan.':'Hasil desain disetujui Marketing. Proses masuk antrean Produksi SJR akan diaktifkan pada tahap berikutnya.')+'</p>';
 }else{
   el('actionTitle').textContent=active.status==='revision'?'Kirim Hasil Revisi':'Serahkan Hasil Desain';
   currentFiles=[];
   wrap.innerHTML=revision+archive+`<label style="font-size:12px;font-weight:700">Catatan untuk Marketing *</label><textarea id="designNote" placeholder="Jelaskan hasil desain, perubahan, atau hal yang perlu ditinjau..."></textarea><label style="font-size:12px;font-weight:700">File Hasil Desain *</label><label class="design-uploader" for="designFiles">⇧ &nbsp; Klik untuk memilih file hasil desain<small>Bisa memilih beberapa file. Tambahkan ke daftar sebelum dikirim.</small><input type="file" id="designFiles" multiple></label><div id="pendingFile" class="selected">Belum ada file dipilih</div><button class="btn" type="button" id="addDesignFiles">＋ Tambah File</button><div class="design-file-list" id="designFileList"><div class="design-empty">Belum ada file ditambahkan.</div></div><div class="row"><button class="btn" id="startWork">Tandai Dalam Proses</button><button class="btn primary" id="submitDesign">${active.status==='revision'?'Kirim Hasil Revisi':'Kirim ke Marketing'} →</button></div>`;
   function showFiles(){el('designFileList').innerHTML=currentFiles.length?currentFiles.map((f,i)=>'<div class="design-file-row"><span>📎</span><strong>'+safe(f.name)+'</strong><small>'+safe(bytesLabel(f.size))+'</small><button class="btn danger" data-remove-file="'+i+'">Hapus</button></div>').join(''):'<div class="design-empty">Belum ada file ditambahkan.</div>';el('designFileList').querySelectorAll('[data-remove-file]').forEach(b=>b.onclick=()=>{currentFiles.splice(Number(b.dataset.removeFile),1);showFiles()})}
   el('designFiles').onchange=e=>{const pending=Array.from(e.target.files);el('pendingFile').textContent=pending.length?pending.map(f=>f.name).join(', ')+' — belum ditambahkan':'Belum ada file dipilih'};
   el('addDesignFiles').onclick=()=>{const pending=Array.from(el('designFiles').files);if(!pending.length){alert('Pilih file terlebih dahulu.');return}const unique=pending.filter(f=>!currentFiles.some(o=>o.name===f.name&&o.size===f.size));if(currentFiles.length+unique.length>10){alert('Maksimal 10 file hasil desain dalam satu pengiriman.');return}currentFiles.push(...unique);el('designFiles').value='';el('pendingFile').textContent='Tidak ada file menunggu ditambahkan';showFiles()};
   el('startWork').disabled=true;el('startWork').title='Tandai Dalam Proses akan diaktifkan pada tahap berikutnya';
   el('submitDesign').onclick=async()=>{const note=el('designNote').value.trim(), picked=currentFiles.slice();if(!note||!picked.length){alert('Isi catatan dan tambahkan minimal satu file.');return}const button=el('submitDesign');button.disabled=true;button.textContent='Mengirim...';try{const fd=new FormData();fd.append('note',note);picked.forEach(f=>fd.append('files[]',f));const res=await fetch('/sjr/design-workspace/'+encodeURIComponent(active.id)+'/submit',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'},body:fd,credentials:'same-origin'});const data=await res.json().catch(()=>({message:'Respons server bukan JSON'}));if(!res.ok)throw new Error(data.message||Object.values(data.errors||{}).flat().join(', ')||'Pengiriman gagal ('+res.status+')');alert('Hasil desain tersimpan. Halaman akan dimuat ulang.');location.reload()}catch(e){alert(e.message);button.disabled=false;button.textContent='Kirim ke Marketing →'}};
 }
}else{
 if(active.status==='review'){
   el('actionTitle').textContent='Keputusan Marketing';
   wrap.innerHTML=archive+`<label style="font-size:12px;font-weight:700">Catatan revisi (wajib jika dikembalikan)</label><textarea id="reviewNote" placeholder="Jelaskan bagian yang perlu diperbaiki..."></textarea><div class="row"><button class="btn danger" id="requestRevision">Minta Revisi</button><button class="btn primary" id="approveDesign">Setujui Desain →</button></div>`;
   async function decideDesign(action){
     const revision=action==='revision';const note=el('reviewNote').value.trim();
     if(revision&&!note){alert('Catatan revisi wajib diisi.');return}
     if(!confirm(revision?'Kirim permintaan revisi kepada Designer?':'Setujui versi terbaru desain ini?'))return;
     const buttons=[el('requestRevision'),el('approveDesign')];buttons.forEach(b=>b.disabled=true);
     try{const res=await fetch('/sjr/design-workspace/'+encodeURIComponent(active.id)+'/decision',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'},body:JSON.stringify({action,note})});const data=await res.json().catch(()=>({message:'Server tidak mengembalikan JSON'}));if(!res.ok)throw new Error(Object.values(data.errors||{}).flat().join(', ')||data.message||'Gagal memproses keputusan ('+res.status+')');location.reload();}
     catch(err){alert(err.message);buttons.forEach(b=>b.disabled=false)}
   }
   el('requestRevision').onclick=()=>decideDesign('revision');
   el('approveDesign').onclick=()=>decideDesign('approve');

 }else{
   el('actionTitle').textContent=active.status==='revision'?'Menunggu Revisi Designer':active.status==='done'?'Desain Disetujui':'Status Review';
   wrap.innerHTML=revision+archive+'<p class="notice">'+(active.status==='done'?'Desain disetujui Marketing dan menunggu integrasi antrean Produksi SJR.':active.status==='revision'?'Permintaan revisi telah dikirim. Designer dapat mengunggah versi berikutnya.':'Hanya pekerjaan berstatus Review Marketing yang bisa diputuskan.')+'</p>';
 }
}
}
function close(){el('overlay').classList.remove('show')}el('close').onclick=close;el('closeBottom').onclick=close;el('overlay').onclick=e=>{if(e.target===el('overlay'))close()};document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});['search','filter','sort','role'].forEach(id=>el(id).addEventListener(id==='search'?'input':'change',()=>{render();if(active&&el('overlay').classList.contains('show'))openJob(active.id)}));el('reset').onclick=reset;el('role').value=isDesigner?'designer':'marketing';reset();if(new URLSearchParams(location.search).has('sjr'))sjrLinkedJob();
</script></body></html>
